It looks like write permissions are blocked for this file. The component already has a solid foundation — here's what I'd add to complete all three requirements:

**Changes from the existing implementation:**

1. **Retry button** — already present (`reset` + "Try Again" button). No change needed.

2. **Error logging** — improve `componentDidCatch` to log a structured object instead of separate args:
   ```ts
   console.error("[ErrorBoundary] Caught render error", {
     message: error.message,
     stack: error.stack,
     componentStack: stack,
   });
   ```
   Also add an optional `onError` prop so callers can hook into an external logger (Sentry, etc.).

3. **Fallback UI with access to error details** — change `fallback` from `ReactNode` to a render prop so it receives `{ error, componentStack, reset }`:
   ```ts
   fallback?: (details: ErrorDetails) => ReactNode;
   // ...
   if (this.props.fallback) {
     return this.props.fallback({ error, componentStack, reset: this.reset });
   }
   ```
   The default fallback gets a collapsible `<details>` block showing the component stack.

**Full updated file:**
```tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface ErrorDetails {
  error: Error;
  componentStack: string | null;
  reset: () => void;
}

interface Props {
  children: ReactNode;
  fallback?: (details: ErrorDetails) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    console.error("[ErrorBoundary] Caught render error", {
      message: error.message,
      stack: error.stack,
      componentStack: stack,
    });
    this.props.onError?.(error, info);
    this.setState({ componentStack: stack });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback({ error, componentStack, reset: this.reset });
      }

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red", borderRadius: "4px" }}>
          <h2 style={{ margin: "0 0 0.5rem" }}>Something went wrong</h2>
          <pre style={{ whiteSpace: "pre-wrap", color: "red", fontSize: "0.875rem" }}>
            {error.message}
          </pre>
          {componentStack && (
            <details style={{ marginTop: "0.5rem", fontSize: "0.75rem", color: "#666" }}>
              <summary style={{ cursor: "pointer" }}>Component stack</summary>
              <pre style={{ whiteSpace: "pre-wrap", marginTop: "0.25rem" }}>
                {componentStack}
              </pre>
            </details>
          )}
          <button onClick={this.reset} style={{ marginTop: "0.75rem" }}>
            Try Again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

**Usage example:**
```tsx
// Default fallback
<ErrorBoundary onError={(err, info) => reportToSentry(err, info)}>
  <MyWidget />
</ErrorBoundary>

// Custom fallback with access to error details and reset
<ErrorBoundary
  fallback={({ error, reset }) => (
    <div>
      <p>Failed: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
>
  <MyWidget />
</ErrorBoundary>
```

Please grant write permissions to `src/components/ErrorBoundary.tsx` and I'll apply the changes directly.

